component.demoCode:
"use client"

import { useState } from "react"
import GlimmProvider, {
  useGlimm,
  type Direction,
} from "@/components/ui/glimm-transition"

const DIRECTIONS: Direction[] = ["ltr", "rtl", "ttb", "btt"]

function DirectionDemo() {
  const { sweep } = useGlimm()
  const [active, setActive] = useState<Direction>("ltr")

  return (
    <div className="flex h-screen min-h-[350px] w-full flex-col items-center justify-center gap-8 bg-background text-foreground">
      <p className="font-mono text-5xl font-medium tracking-tight">{active}</p>
      <div className="flex gap-2">
        {DIRECTIONS.map((direction) => (
          <button
            key={direction}
            type="button"
            onClick={() => sweep(() => setActive(direction), { direction })}
            className={`rounded-full border px-4 py-1.5 font-mono text-sm transition-colors ${
              active === direction
                ? "border-foreground bg-foreground text-background"
                : "border-border hover:bg-muted"
            }`}
          >
            {direction}
          </button>
        ))}
      </div>
    </div>
  )
}

export default function Directions() {
  return (
    <GlimmProvider palette="azure">
      <DirectionDemo />
    </GlimmProvider>
  )
}
